    val easeOut = CubicBezierEasing(0.22f, 1f, 0.36f, 1f) // Default for anything entering or responding to touch.
    val easeIn = CubicBezierEasing(0.64f, 0f, 0.78f, 0f) // Anything leaving the screen.
    val easeInOut = CubicBezierEasing(0.65f, 0f, 0.35f, 1f) // Things that move from one place to another and stay (segmented thumb, tab indicator).
